import './styles.css';
import { useState, useEffect, useCallback } from 'react';

interface Sample {
  id: number;
  quality: number; // 0-1, how "real" it looks
  isReal: boolean;
}

function generateFakeSample(generatorSkill: number): Sample {
  // Quality depends on generator skill (0-1) with some randomness
  const quality = Math.min(1, Math.max(0, generatorSkill * 0.7 + Math.random() * 0.3));
  return {
    id: Date.now() + Math.random(),
    quality,
    isReal: false,
  };
}

function generateRealSample(): Sample {
  // Real samples have high quality with slight variation
  return {
    id: Date.now() + Math.random(),
    quality: 0.85 + Math.random() * 0.15,
    isReal: true,
  };
}

function SampleCard({ sample, discriminatorGuess, revealed }: { 
  sample: Sample; 
  discriminatorGuess: 'real' | 'fake' | null;
  revealed: boolean;
}) {
  const isCorrect = revealed && (
    (discriminatorGuess === 'real' && sample.isReal) ||
    (discriminatorGuess === 'fake' && !sample.isReal)
  );
  const isWrong = revealed && !isCorrect;

  // Visual representation based on quality
  const getPattern = (quality: number) => {
    const smoothness = quality * 100;
    const coherence = quality * 255;
    return {
      background: `linear-gradient(${45 + quality * 90}deg, 
        hsl(${260 + quality * 40}, ${50 + quality * 30}%, ${40 + quality * 20}%), 
        hsl(${280 + quality * 60}, ${40 + quality * 40}%, ${50 + quality * 25}%))`,
      filter: `blur(${(1 - quality) * 2}px)`,
    };
  };

  const pattern = getPattern(sample.quality);

  return (
    <div className={`sample-card ${revealed ? (isCorrect ? 'correct' : 'wrong') : ''}`}>
      <div className="sample-image" style={pattern}>
        <div className="sample-noise" style={{ opacity: (1 - sample.quality) * 0.5 }} />
      </div>
      <div className="sample-info">
        {!revealed && discriminatorGuess && (
          <span className={`guess ${discriminatorGuess}`}>
            Thinks: {discriminatorGuess}
          </span>
        )}
        {revealed && (
          <>
            <span className={`truth ${sample.isReal ? 'real' : 'fake'}`}>
              Actually: {sample.isReal ? 'REAL' : 'FAKE'}
            </span>
            <span className={isCorrect ? 'result-correct' : 'result-wrong'}>
              {isCorrect ? 'Caught!' : 'Fooled!'}
            </span>
          </>
        )}
      </div>
    </div>
  );
}

function SkillMeter({ label, value, color }: { label: string; value: number; color: string }) {
  return (
    <div className="skill-meter">
      <div className="skill-header">
        <span className="skill-label">{label}</span>
        <span className="skill-value">{Math.round(value * 100)}%</span>
      </div>
      <div className="skill-track">
        <div 
          className="skill-fill" 
          style={{ width: `${value * 100}%`, background: color }}
        />
      </div>
    </div>
  );
}

export default function App() {
  const [generatorSkill, setGeneratorSkill] = useState(0.2);
  const [discriminatorSkill, setDiscriminatorSkill] = useState(0.3);
  const [samples, setSamples] = useState<Sample[]>([]);
  const [guesses, setGuesses] = useState<Record<number, 'real' | 'fake'>>({});
  const [revealed, setRevealed] = useState(false);
  const [round, setRound] = useState(0);
  const [isTraining, setIsTraining] = useState(false);
  const [history, setHistory] = useState<{ genWins: number; discWins: number }[]>([]);

  const generateRound = useCallback(() => {
    const newSamples: Sample[] = [];
    // Generate 2-3 fakes and 1-2 reals
    const numFakes = 2 + Math.floor(Math.random() * 2);
    const numReals = 1 + Math.floor(Math.random() * 2);

    for (let i = 0; i < numFakes; i++) {
      newSamples.push(generateFakeSample(generatorSkill));
    }
    for (let i = 0; i < numReals; i++) {
      newSamples.push(generateRealSample());
    }

    // Shuffle
    newSamples.sort(() => Math.random() - 0.5);

    // Discriminator makes guesses based on its skill
    const newGuesses: Record<number, 'real' | 'fake'> = {};
    newSamples.forEach(sample => {
      // Probability of correct guess depends on skill and sample quality difference
      const qualitySignal = sample.isReal ? sample.quality : (1 - sample.quality);
      const correctProb = discriminatorSkill * 0.5 + qualitySignal * 0.5;
      const correct = Math.random() < correctProb;
      newGuesses[sample.id] = correct 
        ? (sample.isReal ? 'real' : 'fake')
        : (sample.isReal ? 'fake' : 'real');
    });

    setSamples(newSamples);
    setGuesses(newGuesses);
    setRevealed(false);
    setRound(r => r + 1);
  }, [generatorSkill, discriminatorSkill]);

  const revealResults = () => {
    setRevealed(true);

    // Calculate who won this round
    let genWins = 0;
    let discWins = 0;
    samples.forEach(sample => {
      const guess = guesses[sample.id];
      const correct = (guess === 'real' && sample.isReal) || (guess === 'fake' && !sample.isReal);
      if (!sample.isReal) {
        // For fakes: if discriminator was fooled, generator wins
        if (!correct) genWins++;
        else discWins++;
      }
    });

    setHistory(h => [...h, { genWins, discWins }]);

    // Update skills based on results
    const genImprovement = genWins > discWins ? 0.05 : 0.02;
    const discImprovement = discWins > genWins ? 0.05 : 0.02;

    setTimeout(() => {
      setGeneratorSkill(s => Math.min(0.95, s + genImprovement));
      setDiscriminatorSkill(s => Math.min(0.95, s + discImprovement));
    }, 1000);
  };

  const autoTrain = () => {
    setIsTraining(true);
    let rounds = 0;

    const trainStep = () => {
      if (rounds >= 5) {
        setIsTraining(false);
        return;
      }
      generateRound();
      setTimeout(() => {
        revealResults();
        rounds++;
        setTimeout(trainStep, 1500);
      }, 1000);
    };

    trainStep();
  };

  const reset = () => {
    setGeneratorSkill(0.2);
    setDiscriminatorSkill(0.3);
    setSamples([]);
    setGuesses({});
    setRevealed(false);
    setRound(0);
    setHistory([]);
    setIsTraining(false);
  };

  useEffect(() => {
    generateRound();
  }, []);

  const totalGenWins = history.reduce((sum, h) => sum + h.genWins, 0);
  const totalDiscWins = history.reduce((sum, h) => sum + h.discWins, 0);

  return (
    <div className="app">
      <div className="header">
        <h1>GAN Playground</h1>
        <p className="subtitle">
          Generator creates fakes. Discriminator tries to catch them. Watch them compete!
        </p>
      </div>

      <div className="players">
        <div className="player generator">
          <div className="player-icon">G</div>
          <div className="player-info">
            <h3>Generator</h3>
            <p>Creates fake samples</p>
            <SkillMeter label="Skill" value={generatorSkill} color="#10b981" />
          </div>
        </div>

        <div className="vs">VS</div>

        <div className="player discriminator">
          <div className="player-icon">D</div>
          <div className="player-info">
            <h3>Discriminator</h3>
            <p>Spots the fakes</p>
            <SkillMeter label="Skill" value={discriminatorSkill} color="#ef4444" />
          </div>
        </div>
      </div>

      <div className="round-display">
        <span className="round-label">Round {round}</span>
        {history.length > 0 && (
          <span className="score">
            Generator: {totalGenWins} | Discriminator: {totalDiscWins}
          </span>
        )}
      </div>

      <div className="samples-section">
        <h3>This Round's Samples</h3>
        <p className="samples-hint">
          Can the Discriminator tell which are fake?
        </p>
        <div className="samples-grid">
          {samples.map(sample => (
            <SampleCard
              key={sample.id}
              sample={sample}
              discriminatorGuess={guesses[sample.id]}
              revealed={revealed}
            />
          ))}
        </div>
      </div>

      <div className="controls">
        {!revealed ? (
          <button onClick={revealResults} className="btn reveal" disabled={isTraining}>
            Reveal Results
          </button>
        ) : (
          <button onClick={generateRound} className="btn next" disabled={isTraining}>
            Next Round
          </button>
        )}
        <button onClick={autoTrain} className="btn train" disabled={isTraining}>
          {isTraining ? 'Training...' : 'Auto-Train 5 Rounds'}
        </button>
        <button onClick={reset} className="btn reset" disabled={isTraining}>
          Reset
        </button>
      </div>

      <div className="insight-box">
        <h3>The Adversarial Dance</h3>
        <p>
          <strong>Generator:</strong> Improves by studying what the Discriminator catches. Creates better fakes over time.
        </p>
        <p>
          <strong>Discriminator:</strong> Improves by seeing more examples. Gets better at spotting subtle flaws.
        </p>
        <p>
          Watch how both skill bars increase as they train! This competition drives both to improve—that's the magic of GANs.
        </p>
      </div>
    </div>
  );
}

