  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.95rem;
}

.players {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 1rem;
}

.player {
  background: rgba(255, 255, 255, 0.05);
  border: 2px solid;
  border-radius: 1rem;
  padding: 1rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  flex: 1;
  max-width: 280px;
}

.player.generator {
  border-color: #10b981;
}

.player.discriminator {
  border-color: #ef4444;
}

.player-icon {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: white;
}

.generator .player-icon {
  background: #10b981;
}

.discriminator .player-icon {
  background: #ef4444;
}

.player-info h3 {
  color: white;
  font-size: 1rem;
  margin-bottom: 0.15rem;
}

.player-info p {
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.75rem;
  margin-bottom: 0.5rem;
}

.vs {
  color: #6b7280;
  font-weight: 700;
  font-size: 1rem;
}

.skill-meter {
  width: 100%;
}

.skill-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.7rem;
  color: rgba(255, 255, 255, 0.7);
  margin-bottom: 0.25rem;
}

.skill-value {
  font-weight: 600;
  color: white;
}

.skill-track {
  height: 6px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
  overflow: hidden;
}

.skill-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.5s ease-out;
}

.round-display {
  text-align: center;
  margin-bottom: 1rem;
}

.round-label {
  color: #9ca3af;
  font-size: 0.9rem;
}

.score {
  display: block;
  color: white;
  font-weight: 600;
  margin-top: 0.25rem;
}

.samples-section {
  background: rgba(255, 255, 255, 0.05);
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.samples-section h3 {
  color: white;
  font-size: 1rem;
  margin-bottom: 0.25rem;
}

.samples-hint {
  color: #9ca3af;
  font-size: 0.85rem;
  margin-bottom: 1rem;
}

.samples-grid {
