  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 1rem;
}

.sample-card {
  background: rgba(255, 255, 255, 0.05);
  border: 2px solid rgba(255, 255, 255, 0.1);
  border-radius: 0.75rem;
  overflow: hidden;
  transition: all 0.3s;
}

.sample-card.correct {
  border-color: #10b981;
}

.sample-card.wrong {
  border-color: #ef4444;
}

.sample-image {
  height: 100px;
  position: relative;
  overflow: hidden;
}

.sample-noise {
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
}

.sample-info {
  padding: 0.75rem;
  text-align: center;
  min-height: 60px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.25rem;
}

.guess {
  font-size: 0.8rem;
  padding: 0.25rem 0.5rem;
  border-radius: 0.25rem;
}

.guess.real {
  color: #10b981;
  background: rgba(16, 185, 129, 0.1);
}

.guess.fake {
  color: #f59e0b;
  background: rgba(245, 158, 11, 0.1);
}

.truth {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

.truth.real {
  color: #10b981;
}

.truth.fake {
  color: #f59e0b;
}

.result-correct {
  color: #10b981;
  font-size: 0.85rem;
  font-weight: 600;
}

.result-wrong {
  color: #ef4444;
  font-size: 0.85rem;
  font-weight: 600;
}

.controls {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.btn {
  flex: 1;
  min-width: 120px;
  padding: 0.75rem 1rem;
  border: none;
  border-radius: 0.5rem;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.btn.reveal {
  background: #8b5cf6;
  color: white;
}

.btn.next {
  background: #10b981;
  color: white;
}

.btn.train {
  background: #f59e0b;
  color: white;
}

.btn.reset {
  background: #374151;
  color: white;
}

.btn:hover:not(:disabled) {
  opacity: 0.9;
  transform: translateY(-1px);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.insight-box {
  background: rgba(255, 255, 255, 0.05);
  border-radius: 1rem;
  padding: 1.25rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.insight-box h3 {
  color: white;
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 0.5rem;
}

.insight-box p:last-child {
